// Step 1 — define the service in .proto
syntax = "proto3";

service OrderService {
  rpc GetOrder    (OrderRequest)  returns (OrderResponse);
  rpc CreateOrder (CreateRequest) returns (OrderResponse);
  rpc StreamOrders(UserRequest)   returns (stream OrderResponse);
}

message OrderRequest  { string order_id = 1; }
message CreateRequest { string item = 1; int32 qty = 2; }
message OrderResponse { string id = 1; string status = 2; double total = 3; }
message UserRequest   { string user_id = 1; }

